SELECT
    (SELECT COUNT(*)
     FROM t_material m
     WHERE m.course_id = #{courseId}
       AND m.uploaded_by = #{userId}
       AND m.is_deleted = 0)                                      AS material_count,

    (SELECT COUNT(*)
     FROM t_material m
     WHERE m.course_id = #{courseId}
       AND m.uploaded_by = #{userId}
       AND m.is_deleted = 0
       AND m.status = 'READY')                                    AS ready_material_count,

    (SELECT COUNT(*)
     FROM t_conversation c
     WHERE c.course_id = #{courseId}
       AND c.user_id = #{userId}
       AND c.is_deleted = 0)                                      AS conversation_count,

    (SELECT COUNT(*)
     FROM t_message msg
     INNER JOIN t_conversation c ON msg.conversation_id = c.id
     WHERE c.course_id = #{courseId}
       AND c.user_id = #{userId}
       AND c.is_deleted = 0
       AND msg.is_deleted = 0
       AND msg.role = 'USER')                                     AS question_count,

    (SELECT AVG(q.correct / q.total)
     FROM t_quiz_attempt q
     WHERE q.course_id = #{courseId}
       AND q.user_id = #{userId}
       AND q.is_deleted = 0
       AND q.submitted_at IS NOT NULL
       AND q.total > 0)                                          AS quiz_accuracy
